            const rebuyReady = hasPerm(state, "Temur Sabertooth") || hasPerm(state, "Cloudstone Curio") || hasAshaya && hasRanger || koglaWitnessReady && (inHand("beast_within") || gy.includes("Beast Within") || inHand("legolas_quick_reflexes") || gy.includes("Legolas's Quick Reflexes") || hasAshaya && (inHand("crop_rotation") || gy.includes("Crop Rotation")) || hasAshaya && hasRanger && hasPerm(state, "Elvish Reclaimer"));
